<div class="table-wrap"><table class="table"><thead><tr><th>Fonte</th><th>Stato</th><th>Processati</th><th>Duplicati</th><th>Errori</th><th>Creato</th></tr></thead><tbody><?php foreach ($imports as $import): ?><tr><td><?php echo e($import['source']); ?></td><td><span class="tag <?php echo strtolower($import['status']) === 'error' ? 'status-error' : 'status-active'; ?>"><?php echo e($import['status']); ?></span></td><td><?php echo e((string) $import['processed']); ?></td><td><?php echo e((string) $import['duplicates']); ?></td><td><?php echo e((string) $import['errors']); ?></td><td><?php echo e($import['created_at']); ?></td></tr><?php endforeach; ?></tbody></table></div>
